22	        String householdId = owner.getHouseholdId();
23	        int count = 0;
24	        for (Owner existing : ownerRepository.findAll()) {
25	            if (householdId != null && householdId.equals(existing.getHouseholdId())) {
26	                count++;
27	            }
28	        }
29	        owner.setHouseholdMemberCount(count + 1); // + 1 for this still-unsaved owner
30	    }
