1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * The identity of an owner's household, keyed on its {@code lastName} and {@code postcode}. The last
12	 * name is normalized (surrounding whitespace stripped, internal runs collapsed to a single space,
13	 * lower-cased) and the postcode is stripped, so incidental casing or spacing does not split a
14	 * household. Two owners belong to the same household when their {@link #householdId()} values are equal.
15	 *
16	 * <p>The {@code householdId} is <em>deterministic</em>: the first 12 hex characters of
17	 * {@code SHA-256(normalizedLastName + '|' + postcode)}. Owners with the same last name and postcode
18	 * therefore share it automatically, with no bookkeeping or minting — there is no longer any
19	 * donor-owner hand-off. An owner with no postcode has no household to key on, so its
20	 * {@code householdId} is {@code null}.
21	 *
22	 * <p>This is the single definition of "same household" shared by {@link AssignHousehold} (which stamps
23	 * the computed id onto the new owner) and {@link CheckOwnerHouseholdUnique} (which rejects a second,
24	 * undeclared member of the same household). Changing the keying rule — e.g. including city or
25	 * normalizing the postcode differently — happens here, once.
26	 */
27	public record OwnerHousehold(String lastName, String postcode) {
28	
29	    public OwnerHousehold {
30	        lastName = normalizeLastName(lastName);
31	        postcode = postcode == null ? "" : postcode.strip();
32	    }
33	
34	    public static OwnerHousehold of(Owner owner) {
35	        return new OwnerHousehold(owner.getLastName(), owner.getPostcode());
36	    }
37	
38	    /**
39	     * The deterministic household identifier: the first 12 hex characters of
40	     * {@code SHA-256(normalizedLastName + '|' + postcode)}, or {@code null} when there is no postcode
41	     * to key the household on.
42	     */
43	    public String householdId() {
44	        if (postcode.isEmpty()) {
45	            return null;
46	        }
47	        return sha256hex(lastName + "|" + postcode).substring(0, 12);
48	    }
49	
50	    /** Lower-cases and collapses whitespace so the household key ignores case and incidental spacing. */
51	    private static String normalizeLastName(String value) {
52	        if (value == null) {
53	            return "";
54	        }
55	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
56	    }
57	
58	    /** Lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
59	    private static String sha256hex(String value) {
60	        try {
61	            byte[] digest = MessageDigest.getInstance("SHA-256")
62	                    .digest(value.getBytes(StandardCharsets.UTF_8));
63	            StringBuilder sb = new StringBuilder(digest.length * 2);
64	            for (byte b : digest) {
65	                sb.append(Character.forDigit((b >> 4) & 0xF, 16));
66	                sb.append(Character.forDigit(b & 0xF, 16));
67	            }
68	            return sb.toString();
69	        }
70	        catch (NoSuchAlgorithmException e) {
71	            throw new IllegalStateException("SHA-256 not available", e);
72	        }
73	    }
74	}
