1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	import java.util.Set;
6	
7	/**
8	 * Business-day rules for owner registration on {@code POST /api/owners}. The effective registration
9	 * date must fall on a business day: when it is a Saturday, Sunday or a listed public holiday it rolls
10	 * forward to the next non-holiday weekday. The effective date is the one supplied in the request, or
11	 * the server's current date when the request omits it; either way the same roll-forward applies, so
12	 * every value derived from the registration date (the membership number's year segment, the per-day
13	 * create-limit bucket) is computed from the adjusted date.
14	 */
15	final class BusinessDay {
16	
17	    /** Fixed public-holiday calendar; a date landing on one of these rolls forward. */
18	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
19	            LocalDate.of(2026, 1, 1),
20	            LocalDate.of(2026, 1, 26),
21	            LocalDate.of(2026, 4, 25),
22	            LocalDate.of(2026, 12, 25),
23	            LocalDate.of(2026, 12, 28));
24	
25	    private BusinessDay() {
26	    }
27	
28	    /**
29	     * Rolls a date forward to the next non-holiday business day; a weekday that is not a public
30	     * holiday is returned unchanged. Weekends and listed public holidays are skipped, repeatedly, so
31	     * a holiday falling on (or adjacent to) a weekend still lands on a clear business day.
32	     */
33	    static LocalDate rollForward(LocalDate date) {
34	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
35	            date = date.plusDays(1);
36	        }
37	        return date;
38	    }
39	
40	    private static boolean isWeekend(LocalDate date) {
41	        DayOfWeek dow = date.getDayOfWeek();
42	        return dow == DayOfWeek.SATURDAY || dow == DayOfWeek.SUNDAY;
43	    }
44	
45	    /**
46	     * The effective, business-day registration date for a create: the supplied date when present,
47	     * otherwise the server's current date, rolled forward off any weekend or public holiday.
48	     */
49	    static LocalDate effective(LocalDate supplied) {
50	        return rollForward(supplied != null ? supplied : LocalDate.now());
51	    }
52	}
