10	 *   <li>+{@link #POINTS_EMAIL} (2) when an email is present;</li>
11	 *   <li>+{@link #POINTS_UNIQUE_NAME} (1) when the owner's {@code namesakeCount} is 0 (the name was
12	 *       unique on create);</li>
13	 *   <li>+{@link #POINTS_HOUSEHOLD} (2) for a household of {@link #HOUSEHOLD_SIZE_FOR_POINTS} (3) or
14	 *       more members;</li>
15	 *   <li>+{@link #POINTS_TENURE} (3) when the owner's tenure exceeds
16	 *       {@link #TENURE_FISCAL_YEARS_FOR_POINTS} (1) elapsed fiscal year.</li>
17	 * </ul>
18	 *
19	 * <p>The points total maps to a numeric level: 1 for 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6 or
20	 * more.
21	 *
22	 * <p>This is the single source of truth for the computation shared by {@code OwnerMapper} (the
23	 * {@code membershipPoints} and {@code membershipLevel} response fields) and the create audit line.
24	 */
25	public final class MembershipLevel {
26	
27	    /** The highest level this rule awards. */
28	    public static final int MAX = 4;
29	
30	    /** Points added when the owner has an email. */
31	    public static final int POINTS_EMAIL = 2;
32	
33	    /** Points added when the owner's name was unique on create ({@code namesakeCount} is 0). */
34	    public static final int POINTS_UNIQUE_NAME = 1;
35	
36	    /** Points added for a household of {@link #HOUSEHOLD_SIZE_FOR_POINTS} or more members. */
37	    public static final int POINTS_HOUSEHOLD = 2;
38	
39	    /** Points added when the owner's tenure exceeds {@link #TENURE_FISCAL_YEARS_FOR_POINTS}. */
40	    public static final int POINTS_TENURE = 3;
41	
42	    /** A household needs at least this many members to earn {@link #POINTS_HOUSEHOLD}. */
43	    public static final int HOUSEHOLD_SIZE_FOR_POINTS = 3;
44	
45	    /**
46	     * An owner's tenure must exceed this many elapsed fiscal years to earn {@link #POINTS_TENURE}.
47	     * Tenure is counted in fiscal years (which start on 1 July, see {@link FiscalYear}), not in
48	     * 365-day windows.
49	     */
50	    public static final long TENURE_FISCAL_YEARS_FOR_POINTS = 1;
51	
52	    private MembershipLevel() {
53	    }
54	
55	    /**
56	     * Compute the membership points for an owner.
57	     *
58	     * @param owner the owner; its {@code email}, {@code namesakeCount}, {@code householdMemberCount}
59	     *              and tenure drive the result
60	     * @return the points total, 0 or greater
61	     */
62	    public static int points(Owner owner) {
63	        int points = 0;
64	        if (owner.hasEmail()) {
65	            points += POINTS_EMAIL;
66	        }
67	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
68	            points += POINTS_UNIQUE_NAME;
69	        }
70	        if (owner.getHouseholdMemberCount() != null
71	                && owner.getHouseholdMemberCount() >= HOUSEHOLD_SIZE_FOR_POINTS) {
72	            points += POINTS_HOUSEHOLD;
73	        }
74	        if (tenureFiscalYears(owner) > TENURE_FISCAL_YEARS_FOR_POINTS) {
75	            points += POINTS_TENURE;
76	        }
77	        return points;
78	    }
79	
80	    /**
81	     * Compute the membership level for an owner by mapping its {@link #points(Owner) points}.
82	     *
83	     * @param owner the owner
84	     * @return the level, between 1 and {@link #MAX} inclusive
85	     */
86	    public static int of(Owner owner) {
87	        return levelForPoints(points(owner));
88	    }
89	
90	    /**
91	     * Map a points total to a membership level: 1 for 0-1 points, 2 for 2-3, 3 for 4-5, 4 for 6 or
92	     * more.
93	     *
94	     * @param points the points total
95	     * @return the level, between 1 and {@link #MAX} inclusive
96	     */
97	    public static int levelForPoints(int points) {
98	        if (points >= 6) {
99	            return 4;
100	        }
101	        if (points >= 4) {
102	            return 3;
103	        }
104	        if (points >= 2) {
105	            return 2;
106	        }
107	        return 1;
108	    }
109	
110	    /**
111	     * Fiscal years elapsed since the owner's registration date - the count of 1 July boundaries
112	     * crossed between registration and today - or 0 when the registration date is unknown (e.g. a
113	     * brand-new owner being created). Never negative for a future registration date.
114	     */
115	    private static long tenureFiscalYears(Owner owner) {
116	        LocalDate registrationDate = owner.getRegistrationDate();
117	        if (registrationDate == null) {
118	            return 0;
119	        }
120	        long years = FiscalYear.startYearOf(LocalDate.now()) - FiscalYear.startYearOf(registrationDate);
121	        return Math.max(years, 0);
122	    }
123	}
